// DIARY — дневник с лором
// ═══════════════════════════════════════════════════════
// Тексты концовок для дневника
var DIARY_ENDING_NOTES = {
  run: 'К1: ЛОЖНАЯ СВОБОДА\n\nКак только часы бьют 16:00, ты активируешь дымовые шашки. Офис заполняется густым едким дымом. Ты выпрыгиваешь в окно, перелетаешь через забор, чувствуя невероятную лёгкость в теле. Ты бежишь к лесу, думая, что спасся...\n\n───────────────────────────────────\n\nИтог: Из тени деревьев выходят двое в чёрной броне. Электрошокер в шею, и мир гаснет. Ты приходишь в себя в белой комнате, привязанный к столу.\n\n«Объект 499 продемонстрировал уникальную физическую адаптацию. Начинайте вивисекцию. Посмотрим, что у него вместо сердца».\n\nТы стал их вечным подопытным.',
  stay: 'К2: ВЕРНОСТЬ ДОЛГУ\n\nТы решаешь верить до конца. Или тебе просто всё равно. Ты сидишь в кресле, глядя в мониторы. Снаружи беснуются аномалии — Сталкер и Ползун словно сошли с ума, они чуют кровь тех, кто приехал за тобой. Группа зачистки не может подойти к двери, потому что монстры рвут их на части.\n\n───────────────────────────────────\n\nИтог: Контора понимает, что живым тебя не взять. Они просто активируют систему удалённо. Ты слышишь тихий шипящий звук из вентиляции. Твои лёгкие кристаллизуются за 4 секунды. Ты застываешь в кресле, как памятник самому себе.\n\nНа мониторах — только статика.',
  risk: 'К3: ВСТРЕЧА С ВОЛКОВЫМ\n\nТы не стал ждать, пока газ просочится сквозь уплотнители твоей гермодвери. Ты схватил обрез, выключил все мониторы и прожекторы. Тьма окутала офис.\n\n— Хотите моей смерти? Получите её на моих условиях.\n\nТы рванул к лестнице. Газовое облако уже поднималось снизу, серое и тяжёлое. Ты прыгнул к вентиляционному люку в потолке, где обычно пряталась Тень. Она лишь коснулась твоего лица холодным туманом и... расступилась.\n\nТы вылез на крышу. Вокруг не было города. Была только Абсолютная Пустота. Чёрное небо, чёрная земля и гудящая внизу Установка, которая светилась мертвенно-синим светом сквозь щели в кровле.\n\nТы встал на самый край крыши. Внизу, у главных ворот, два чёрных фургона и фигурки людей в химзащите.\n\n— Я ЗНАЮ, ЧТО ВЫ ЗДЕСЬ ДЕЛАЛИ! Я СТАЛ ЧАСТЬЮ ЭТОГО! МНЕ НЕ НУЖНЫ ВАШИ ДЕНЬГИ!\n\nТы почувствовал, как Резонанс в твоей крови достиг пика. Твоё тело начало вибрировать на частоте 440 Гц. Ты сделал шаг вперёд — прямо в бездну.\n\nНо ты не разбился. Пространство вывернулось наизнанку. Стерильный кафельный пол. Запах озона.\n\n───────────────────────────────────\n\nПеред тобой у пульта стоял изможденный человек. «Д-р Волков. Руководитель проекта "Фокус"».\n\n— Пятнадцать смен... Я ставил на то, что ты сломаешься на десятой. Ты — первый, кто пришёл сюда сам, а не в мешке для трупов.\n\nЕго ладонь была такой же полупрозрачной, как твоя.\n\n— Добро пожаловать в реальность, 499-й. Нам нужно выключить этот мир, пока он не выключил нас.\n\nТвоя история только начинается.'
};

var DIARY_ENDING_NAMES = {
  run:  'К1: ЛОЖНАЯ СВОБОДА',
  stay: 'К2: ВЕРНОСТЬ ДОЛГУ',
  risk: 'К3: ВСТРЕЧА С ВОЛКОВЫМ'
};

var DIARY = {
  entries: [],        // [{level, note}]
  endingEntries: [],  // [{type, note}] — концовки К1/К2/К3

  load: function(){
    try {
      var raw = localStorage.getItem('resonance_diary');
      if(raw) this.entries = JSON.parse(raw);
    } catch(e){ this.entries = []; }
    // Always sync note text from current CAMPAIGN.levels (fixes stale localStorage)
    this.entries.forEach(function(e){
      var lvl = CAMPAIGN.levels[e.level];
      if(lvl && lvl.note) e.note = lvl.note;
    });
    // Load ending entries
    try {
      var rawE = localStorage.getItem('resonance_diary_endings');
      if(rawE) this.endingEntries = JSON.parse(rawE);
    } catch(e){ this.endingEntries = []; }
    // Sync ending texts
    var self = this;
    this.endingEntries.forEach(function(e){
      if(DIARY_ENDING_NOTES[e.type]) e.note = DIARY_ENDING_NOTES[e.type];
    });
  },

  save: function(){
    try { localStorage.setItem('resonance_diary', JSON.stringify(this.entries)); } catch(e){}
  },

  saveEndings: function(){
    try { localStorage.setItem('resonance_diary_endings', JSON.stringify(this.endingEntries)); } catch(e){}
  },

  addEntry: function(levelNum){
    var lvl = CAMPAIGN.levels[levelNum];
    if(!lvl) return;
    for(var i=0;i<this.entries.length;i++){
      if(this.entries[i].level === levelNum) return;
    }
    this.entries.push({ level: levelNum, note: lvl.note });
    this.entries.sort(function(a,b){ return a.level - b.level; });
    this.save();
  },

  addEndingEntry: function(type){
    if(!DIARY_ENDING_NOTES[type]) return;
    for(var i=0;i<this.endingEntries.length;i++){
      if(this.endingEntries[i].type === type) return;
    }
    this.endingEntries.push({ type: type, note: DIARY_ENDING_NOTES[type] });
    this.saveEndings();
  },

  reset: function(){
    this.entries = [];
    this.endingEntries = [];
    this.save();
    this.saveEndings();
  }
};

