// Helper functions for achievement checks
function _achSaved(){ try{return JSON.parse(localStorage.getItem('resonance_nights')||'[]')}catch(e){return[];} }
function _achSkills(){ if(typeof ST==='undefined')return 0; return Object.values(ST.unlockedSkills||{}).reduce(function(a,b){return a+b;},0); }
function _achLvl(){ return (typeof LEVEL_SYSTEM!=='undefined')?LEVEL_SYSTEM.level:1; }
function _achDiary(){ if(typeof DIARY==='undefined')return 0; DIARY.load(); return DIARY.entries.length; }

// Track special achievements during game
function trackSpecialAchievements(){
  if(typeof G==='undefined'||!G.gameWon) return;
  if(G.power < 5)  try{localStorage.setItem('ach_close_call','1')}catch(e){}
  if(G.power > 80) try{localStorage.setItem('ach_power_saver','1')}catch(e){}
  if(G.stats && G.stats.doorClosings === 0) try{localStorage.setItem('ach_no_door','1')}catch(e){}
  if(G.stats && G.stats.flashUses === 0)    try{localStorage.setItem('ach_no_flash','1')}catch(e){}
}

// ── Toast-уведомление при получении достижения
function showAchievementToast(ach) {
  var container = document.getElementById('ach-toast');
  if (!container) return;
  var card = document.createElement('div');
  card.className = 'ach-toast-card';
  card.innerHTML =
    '<div class="ach-toast-icon">' + ach.icon + '</div>' +
    '<div class="ach-toast-body">' +
      '<div class="ach-toast-label">ДОСТИЖЕНИЕ РАЗБЛОКИРОВАНО</div>' +
      '<div class="ach-toast-name">' + ach.name + '</div>' +
      '<div class="ach-toast-desc">' + ach.desc + '</div>' +
    '</div>' +
    '<div class="ach-toast-bar"></div>';
  container.appendChild(card);
  setTimeout(function(){
    card.classList.add('ach-toast-out');
    setTimeout(function(){ if(card.parentNode) card.parentNode.removeChild(card); }, 500);
  }, 4200);
}

