function openAchievements(){
  var unlocked = ACHIEVEMENTS.checkAll();
  var total    = ACHIEVEMENTS.defs.length;
  var done     = unlocked.length;
  var pct      = total ? Math.round(done / total * 100) : 0;
  var modal = document.getElementById('achievements-modal');

  var html = '<div class="lm-backdrop" onclick="closeAchievements()"></div>';
  html += '<div class="ach-box">';
  html += '<button class="sm-close" onclick="closeAchievements()">✕</button>';
  html += '<div class="ach-header">';
  html += '<div class="ach-title"><span>ДОСТИЖЕНИЯ</span></div>';
  html += '<div class="ach-progress-row">';
  html += '<div class="ach-counter">'+done+'<span class="ach-counter-sub">РАЗБЛОКИРОВАНО</span></div>';
  html += '<div class="ach-progress-wrap">';
  html += '<div class="ach-global-bar"><div class="ach-global-fill" style="width:'+pct+'%"></div></div>';
  html += '<div class="ach-pct">'+pct+'% · '+done+' / '+total+'</div>';
  html += '</div>';
  html += '</div>';
  html += '</div>';
  html += '<div class="ach-list">';

  _ACH_CATS.forEach(function(cat){
    var defs    = ACHIEVEMENTS.defs.filter(function(a){ return a.cat === cat.id; });
    if(!defs.length) return;
    var catDone = defs.filter(function(a){ return unlocked.indexOf(a.id)>=0; }).length;
    html += '<div class="ach-cat-hdr">';
    html += '<span class="ach-cat-ico">'+cat.icon+'</span>';
    html += '<span class="ach-cat-lbl">'+cat.label+'</span>';
    html += '<span class="ach-cat-cnt">'+catDone+'/'+defs.length+'</span>';
    html += '</div>';
    defs.forEach(function(a){
      var isDone = unlocked.indexOf(a.id)>=0;
      html += '<div class="ach-item'+(isDone?' ach-done':'')+'">';
      html += '<span class="ach-icon">'+(isDone ? a.icon : '🔒')+'</span>';
      html += '<div class="ach-info">';
      html += '<div class="ach-name">'+(isDone ? a.name : '???')+'</div>';
      html += '<div class="ach-desc">'+a.desc+'</div>';
      html += '</div>';
      if(isDone) html += '<span class="ach-check">✓</span>';
      html += '</div>';
    });
  });

  html += '</div></div>';
  modal.innerHTML = html;
  modal.classList.add('active');
}

function closeAchievements(){
  var m=document.getElementById('achievements-modal');
  m.classList.remove('active'); m.innerHTML='';
}

// ═══════════════════════════════════════════════════════
// DIARY VOICE SYSTEM
// ═══════════════════════════════════════════════════════
var DIARY_VOICE = {
  // Map level → audio element id
  tracks: {
    1: 'diary-voice-1',
    2: 'diary-voice-2',
    3: 'diary-voice-3',
    4: 'diary-voice-4',
    5: 'diary-voice-5',
    6: 'diary-voice-6',
    7: 'diary-voice-7'
  },

  // Play voice for a level (called after win)
  _musicWasPaused: false,

  play: function(level){
    var id = this.tracks[level];
    if(!id) return;
    var el = document.getElementById(id);
    if(!el) return;
    // Stop all other voices first
    this.stopAll();
    // Pause game/menu music and remember state
    this._musicWasPaused = false;
    if(typeof AUDIO !== 'undefined' && AUDIO.current){
      var musicEl = AUDIO[AUDIO.current];
      if(musicEl && !musicEl.paused){
        musicEl.pause();
        this._musicWasPaused = true;
      }
    }
    el.currentTime = 0;
    el.volume = 0.85;
    var self = this;
    el.onended = function(){
      self._onVoiceEnded();
    };
    el.play().catch(function(){});
  },

  _onVoiceEnded: function(){
    // Resume music if it was playing before
    if(this._musicWasPaused && typeof AUDIO !== 'undefined' && AUDIO.current){
      var musicEl = AUDIO[AUDIO.current];
      if(musicEl) musicEl.play().catch(function(){});
    }
    this._musicWasPaused = false;
  },

  stop: function(level){
    var id = this.tracks[level];
    if(!id) return;
    var el = document.getElementById(id);
    if(el){ el.pause(); el.currentTime = 0; }
    this._onVoiceEnded();
  },

  stopAll: function(){
    var self = this;
    Object.values(this.tracks).forEach(function(id){
      var el = document.getElementById(id);
      if(el){ el.pause(); el.currentTime = 0; el.onended = null; }
    });
  },

  // Build mini-player HTML for diary page
  playerHtml: function(level){
    var id = this.tracks[level];
    if(!id) return '';
    return '<div class="diary-voice-player" id="dvp-' + level + '">'
      + '<span class="dvp-icon">🎙</span>'
      + '<span class="dvp-label">АУДИО ДНЕВНИК · УРОВЕНЬ ' + level + '</span>'
      + '<button class="dvp-play" onclick="DIARY_VOICE._togglePlay(' + level + ', this)">▶</button>'
      + '<div class="dvp-bar"><div class="dvp-progress" id="dvp-prog-' + level + '"></div></div>'
      + '<span class="dvp-time" id="dvp-time-' + level + '">0:00</span>'
      + '</div>';
  },

  _togglePlay: function(level, btn){
    var id = this.tracks[level];
    if(!id) return;
    var el = document.getElementById(id);
    if(!el) return;

    if(!el.paused){
      el.pause();
      btn.textContent = '▶';
      // Resume music when manually paused
      if(this._musicWasPaused && typeof AUDIO!=='undefined' && AUDIO.current){
        var me = AUDIO[AUDIO.current];
        if(me) me.play().catch(function(){});
        this._musicWasPaused = false;
      }
    } else {
      this.stopAll();
      // Reset all other play buttons
      document.querySelectorAll('.dvp-play').forEach(function(b){ b.textContent = '▶'; });
      // Pause music
      this._musicWasPaused = false;
      if(typeof AUDIO!=='undefined' && AUDIO.current){
        var musicEl = AUDIO[AUDIO.current];
        if(musicEl && !musicEl.paused){ musicEl.pause(); this._musicWasPaused = true; }
      }
      var self = this;
      el.onended = function(){ self._onVoiceEnded(); };
      el.play().catch(function(){});
      btn.textContent = '⏸';

      // Track progress
      var progId = 'dvp-prog-' + level;
      var timeId = 'dvp-time-' + level;
      el._progInterval = setInterval(function(){
        if(el.paused || el.ended){
          clearInterval(el._progInterval);
          btn.textContent = '▶';
          return;
        }
        var pct = el.duration ? (el.currentTime / el.duration * 100) : 0;
        var prog = document.getElementById(progId);
        if(prog) prog.style.width = pct + '%';
        var t = document.getElementById(timeId);
        if(t){
          var m = Math.floor(el.currentTime/60);
          var s = Math.floor(el.currentTime%60);
          t.textContent = m + ':' + (s<10?'0':'')+s;
        }
      }, 250);
    }
  }
};
